import React from "react";
import Link from "next/link";
import Image from "next/image";
import { WORDMARK } from "./wordmarkPaths";

/**
 * Perseus Talent logo, three forms (see LOGO_INTEGRATION_PLAN.md):
 *  - "lockup": emblem (traced medallion) + gold/white wordmark. For purple backgrounds (header, footer, 404).
 *  - "full":   the complete traced logo. For light backgrounds only (purple "TALENT" disappears on purple).
 *  - "emblem": medallion only.
 *
 * Assets are generated by `npm run brand:logo` from brand-source/perseus-logo-original.jpg.
 * The wordmark outlines (Cinzel, OFL) live in wordmarkPaths.ts so there is no web-font dependency.
 */

interface LogoProps {
  variant?: "lockup" | "full" | "emblem";
  /** "header" and "footer" are presets; a number is the emblem height in px (lockup/emblem) or width in px (full). */
  size?: "header" | "footer" | number;
  className?: string;
  linkToHome?: boolean;
}

const GOLD = "#C5A15B";

const EMBLEM_SRC = "/brand/logo-emblem.svg";
const FULL_SRC = "/brand/logo-full.svg";
const FULL_W = 2326;
const FULL_H = 1632;

function Emblem({ className, style, px }: { className?: string; style?: React.CSSProperties; px: number }) {
  return (
    <Image
      src={EMBLEM_SRC}
      alt=""
      width={px}
      height={px}
      unoptimized
      priority
      className={`shrink-0 ${className ?? ""}`}
      style={style}
    />
  );
}

function Wordmark({ className, style }: { className?: string; style?: React.CSSProperties }) {
  const { rules } = WORDMARK;
  return (
    <svg
      viewBox={WORDMARK.viewBox}
      xmlns="http://www.w3.org/2000/svg"
      className={`shrink-0 w-auto ${className ?? ""}`}
      style={style}
      aria-hidden="true"
      focusable="false"
    >
      <path d={WORDMARK.perseus} fill={GOLD} />
      <path d={WORDMARK.talent} fill="#FFFFFF" />
      <line x1={rules.left.x1} y1={rules.left.y} x2={rules.left.x2} y2={rules.left.y} stroke={GOLD} strokeWidth="0.7" />
      <line x1={rules.right.x1} y1={rules.right.y} x2={rules.right.x2} y2={rules.right.y} stroke={GOLD} strokeWidth="0.7" />
    </svg>
  );
}

export function Logo({
  variant = "lockup",
  size = "header",
  className = "",
  linkToHome = true,
}: LogoProps) {
  let rendered: React.ReactNode;

  if (variant === "full") {
    const width = typeof size === "number" ? size : 280;
    rendered = (
      <Image
        src={FULL_SRC}
        alt="Perseus Talent"
        width={FULL_W}
        height={FULL_H}
        unoptimized
        className={`h-auto max-w-full select-none ${className}`}
        style={{ width }}
      />
    );
  } else if (variant === "emblem") {
    const px = typeof size === "number" ? size : size === "footer" ? 64 : 48;
    rendered = <Emblem px={px} className={className} style={{ width: px, height: px }} />;
  } else {
    // lockup
    const isHeader = size === "header";
    const isFooter = size === "footer";
    if (isHeader || isFooter) {
      rendered = (
        <span className={`inline-flex items-center ${isFooter ? "gap-3.5" : "gap-2.5 md:gap-3"} ${className}`}>
          <Emblem
            px={isFooter ? 64 : 48}
            className={isFooter ? "h-16 w-16" : "h-10 w-10 md:h-12 md:w-12"}
          />
          <Wordmark className={isFooter ? "h-[44px]" : "h-[30px] md:h-[34px]"} />
        </span>
      );
    } else {
      const px = typeof size === "number" ? size : 48;
      rendered = (
        <span className={`inline-flex items-center ${className}`} style={{ gap: Math.round(px * 0.25) }}>
          <Emblem px={px} style={{ width: px, height: px }} />
          <Wordmark style={{ height: Math.round(px * 0.6) }} />
        </span>
      );
    }
  }

  if (linkToHome) {
    return (
      <Link
        href="/"
        aria-label="Perseus Talent — home"
        className="inline-flex items-center focus:outline-none focus-visible:ring-2 focus-visible:ring-gold-500 focus-visible:ring-offset-2 rounded-[2px]"
      >
        {rendered}
      </Link>
    );
  }

  return <>{rendered}</>;
}
